2115	@@ -0,0 +1,52 @@
2116	+import 'dart:async';
2117	+
2118	+/// Story 1.5 — lets `core/network`'s `ApiClient` signal a mid-session
2119	+/// `AUTH_EXPIRED` without importing anything from `features/auth` (RNF06:
2120	+/// the domain/data layers of a feature are the only things allowed to know
2121	+/// about each other across that boundary, never the other way from core).
2122	+/// `SessionRepositoryImpl` is the one bridge that turns an event on
2123	+/// [expiredEvents] into the epic's single `SessionStatus.expired` value on
2124	+/// its own `statusStream` (Design Notes).
2125	+///
2126	+/// Pure Dart, no Flutter import — same constraint `ApiClient`/`Failure`
2127	+/// already hold in `core/`.
2128	+abstract class SessionExpiryNotifier {
2129	+  /// Broadcast stream of expiry events. Unlike `SessionRepository
2130	+  /// .statusStream`, this carries no replay semantics: it is a one-shot
2131	+  /// signal per expiry, not a status a late subscriber needs to catch up
2132	+  /// on — only `SessionRepositoryImpl`'s single long-lived subscription
2133	+  /// (wired at construction) is expected to listen.
2134	+  Stream<void> get expiredEvents;
2135	+
2136	+  /// Signals that the current session just expired mid-use (a non-boot
2137	+  /// `AUTH_EXPIRED` response). Never throws.
2138	+  void notifyExpired();
2139	+
2140	+  /// Releases the underlying stream resource.
2141	+  Future<void> dispose();
2142	+}
2143	+
2144	+/// Default implementation — a broadcast `StreamController` wrapped behind
2145	+/// the port above.
2146	+class SessionExpiryNotifierImpl implements SessionExpiryNotifier {
2147	+  final StreamController<void> _controller = StreamController<void>.broadcast();
2148	+
2149	+  @override
2150	+  Stream<void> get expiredEvents => _controller.stream;
2151	+
2152	+  @override
2153	+  void notifyExpired() {
2154	+    // Guards against a call racing `dispose()` (wired to `get_it`'s
2155	+    // `sl.reset()`) — without this, a late `.add()` after `.close()` would
2156	+    // throw an unhandled `StateError` instead of just being a no-op on an
2157	+    // already-torn-down notifier (same rationale as `SessionRepositoryImpl
2158	+    // ._emit`).
2159	+    if (_controller.isClosed) {
2160	+      return;
2161	+    }
2162	+    _controller.add(null);
2163	+  }
2164	+
2165	+  @override
2166	+  Future<void> dispose() => _controller.close();
2167	+}
