88	  Future<Either<Failure, Map<String, dynamic>>> _send(
89	    Future<Response<Map<String, dynamic>>> Function() request,
90	  ) async {
91	    try {
92	      final response = await request();
93	      final data = response.data;
94	      if (data == null) {
95	        return left(
96	          const Failure.malformedResponse(message: 'Empty response body'),
97	        );
98	      }
99	      return right(data);
100	    } on DioException catch (e) {
101	      return left(_mapDioException(e));
102	    } catch (e) {
103	      return left(Failure.malformedResponse(message: e.toString()));
104	    }
105	  }
