107	  Failure _mapDioException(DioException e) {
108	    final code = dioErrorCodeOf(e);
109	    if (code == null) {
110	      // Covers a cancelled request and an HTTP response that doesn't carry
111	      // the expected `{code, message, retryable}` body — neither is one of
112	      // the 13 backend codes, so neither is retryable (dioErrorCodeOf).
113	      return Failure.malformedResponse(
114	        message: e.message ?? 'Malformed response',
115	      );
116	    }
117	    final data = e.response?.data;
118	    final message = data is Map ? data['message'] : null;
119	    final failure = Failure.fromCode(
120	      code,
121	      (message is String ? message : null) ?? e.message ?? 'Unknown error',
122	    );
123	    if (failure is AuthExpired && !_isAnonKeyOnlyCall(e)) {
124	      _sessionExpiryNotifier.notifyExpired();
125	    }
126	    return failure;
127	  }
